<script setup>
import { computed, ref } from 'vue'
import { Badge, Button, FormControl, TabButtons, Tooltip } from 'frappe-ui'
import BooleanSwitch from '@/components/Controls/BooleanSwitch.vue'
import ClearableCombobox from '@/components/Controls/ClearableCombobox.vue'
import ToggleFilter from '@/components/Controls/ToggleFilter.vue'
import UserAvatar from '@/components/UserAvatar.vue'
import ProgressBar from '@/components/ProgressBar.vue'
import FeedbackBanner from '@/components/Assessment/FeedbackBanner.vue'
import SkeletonLoader from '@/components/SkeletonLoader.vue'
import EmptyStateLayout from '@/components/Layouts/EmptyStateLayout.vue'
import CourseCard from '@/components/CourseCard.vue'
import LearnerCourseCard from '@/components/Courses/LearnerCourseCard.vue'
import inventory from '@/component-inventory.json'
import logo from '@/assets/images/ai-coaching-vietnam.png'
const searchText = ref(''), email = ref(''), category = ref(null), certified = ref(false), filterOn = ref(false), selectedTab = ref('published'), query = ref(''), group = ref('')
const categories = [{ label: 'Kế toán', value: 'accounting' }, { label: 'Thuế', value: 'tax' }, { label: 'Tài chính', value: 'finance' }]
const tabs = [{ label: 'Đã xuất bản', value: 'published' }, { label: 'Sắp diễn ra', value: 'upcoming' }]
const sampleInstructor = { full_name: 'Nguyễn Minh Anh', user_image: null }
const sampleCourse = { title: 'Kế toán thuế thực hành', short_introduction: 'Nắm vững kiến thức và thực hành qua các tình huống thường gặp.', category: 'Kế toán', instructors: [], rating: 4.8, lessons: 12, enrollments: 120, paid_course: 1, price: '850.000 ₫' }
const groups = computed(() => [...new Set(inventory.map(item => item.group))].sort((a,b) => a.localeCompare(b)))
const filtered = computed(() => { const term = query.value.trim().toLocaleLowerCase(); return inventory.filter(item => (!group.value || item.group === group.value) && (!term || `${item.name} ${item.path}`.toLocaleLowerCase().includes(term))) })
</script>
